def tallest(heights):
    best = 0
    for i in range(len(heights)):
        if heights[i] > heights[best]:
            best = i
    return best

print(tallest([150, 172, 165]))

def oldest(ages):
    best = 0
    for i in range(len(ages)):
        if ages[i] > ages[best]:
            best = i
    return ages[best]

print(oldest([8, 14, 11]))

